-- schema 10, DDL from historical writer c6f1c85628722e3d687985f1d513a69d531cbc85.
CREATE TABLE discoveries (vehicle_id TEXT NOT NULL, rarity TEXT NOT NULL, PRIMARY KEY(vehicle_id, rarity))
CREATE TABLE gacha_progress (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL, counter INTEGER NOT NULL, tickets INTEGER NOT NULL)
CREATE TABLE gacha_requests (request_id TEXT PRIMARY KEY NOT NULL, command TEXT NOT NULL, settlement_id TEXT NOT NULL, revision INTEGER NOT NULL, counter INTEGER NOT NULL, tickets INTEGER NOT NULL)
CREATE TABLE delivery_lists ( created_on TEXT NOT NULL, band INTEGER NOT NULL, source TEXT NOT NULL, content_version TEXT NOT NULL, rule_version TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY (created_on, band, source, content_version, rule_version))
CREATE TABLE delivery_requests ( request_id TEXT PRIMARY KEY NOT NULL, command TEXT NOT NULL, active TEXT NOT NULL, paid INTEGER NOT NULL CHECK (paid IN (0, 1)))
CREATE TABLE delivery_active (id INTEGER PRIMARY KEY CHECK (id = 1), request_id TEXT NOT NULL UNIQUE)
CREATE TABLE delivery_routes (request_id TEXT PRIMARY KEY NOT NULL, route TEXT NOT NULL, started_at INTEGER NOT NULL)
CREATE TABLE delivery_outcomes (request_id TEXT PRIMARY KEY NOT NULL, command TEXT NOT NULL, result TEXT NOT NULL)
CREATE TABLE delivery_held (request_id TEXT PRIMARY KEY NOT NULL, payload TEXT NOT NULL)
CREATE TABLE delivery_hold_outcomes (request_id TEXT PRIMARY KEY NOT NULL, command TEXT NOT NULL, result TEXT NOT NULL)
CREATE TABLE delivery_changes ( request_id TEXT PRIMARY KEY NOT NULL, command TEXT NOT NULL, active TEXT NOT NULL, paid INTEGER NOT NULL CHECK (paid >= 0), charged INTEGER NOT NULL CHECK (charged IN (0, 1)))
CREATE TABLE delivery_route_history (route TEXT PRIMARY KEY NOT NULL, request_id TEXT NOT NULL)
CREATE TABLE driving_days ( day TEXT NOT NULL, source TEXT NOT NULL, rewarded INTEGER NOT NULL CHECK (rewarded >= 0), PRIMARY KEY (day, source))
CREATE TABLE driving_drives ( drive_id TEXT PRIMARY KEY NOT NULL, command TEXT NOT NULL, recorded INTEGER NOT NULL, rewarded INTEGER NOT NULL, amount INTEGER NOT NULL, day TEXT NOT NULL, day_rewarded INTEGER NOT NULL)
CREATE TABLE material_requests (request_id TEXT PRIMARY KEY NOT NULL, command TEXT NOT NULL, original_state TEXT NOT NULL, result TEXT NOT NULL)
CREATE TABLE repair_requests (request_id TEXT PRIMARY KEY NOT NULL, command TEXT NOT NULL, original_state TEXT NOT NULL, result TEXT NOT NULL)
CREATE TABLE initialization_profile (id INTEGER PRIMARY KEY CHECK(id=1), profile_id TEXT UNIQUE NOT NULL, source TEXT NOT NULL, proof_id TEXT, proof_revision INTEGER, marker_request TEXT)
CREATE TABLE initialization_requests (request_id TEXT PRIMARY KEY NOT NULL, profile_id TEXT UNIQUE NOT NULL, command TEXT NOT NULL, original_state TEXT NOT NULL, result TEXT NOT NULL)
CREATE TABLE first_gift_markers (profile_id TEXT PRIMARY KEY NOT NULL, request_id TEXT UNIQUE NOT NULL, rental_id TEXT NOT NULL, settlement_id TEXT NOT NULL)
CREATE TABLE first_gift_requests (request_id TEXT PRIMARY KEY NOT NULL, profile_id TEXT UNIQUE NOT NULL, command TEXT NOT NULL, original_state TEXT NOT NULL, result TEXT NOT NULL)
CREATE TABLE host_command_checkpoint (id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL, phase INTEGER NOT NULL CHECK(phase IN (0,1)), digest TEXT NOT NULL)
